void doPixelsMatch_1_oe(final int x, final int y, final int a, final int b) {
        if (!componentMatch(a, b, 0, 2)
            || !componentMatch(a, b, 8, 2)
            || !componentMatch(a, b, 16, 2)
            || !componentMatch(a, b, 24, 2)) {

            final String complaint = String.format("Pixel mismatch at (%d,%d): 0x%08x 0x%08x",
                x, y, a, b);
            fail(complaint);
}
}

private void processBadParams_1_oe(final File target, final int x, final int y, final int width, final int height, final String comment) throws IOException{
        final TiffImageParser tiffImageParser = new TiffImageParser();
        try {
            final TiffImagingParameters params = new TiffImagingParameters();
            params.setSubImage(x, y, width, height);
            tiffImageParser.getBufferedImage(target, params);
            fail("Reading TIFF sub-image failed to detect bad parameter: "+comment);
}
}

